// SSOT: SINGLE SOURCE OF TRUTH STATUS CONFIGURATION
// Aligned with imagin-studio-metadata-workflow.md recommended flow:
//   DRAFT → PROCESSING → (metadata_ready | needs_review | rejected) → READY → EXPORTED → SUBMITTED.
// 'processing' = preflight sedang berjalan.
// 'ready'      = user accept hasil review (override pass).
// 'exported'   = CSV sudah di-download ke Adobe workflow.
// 'submitted'  = user konfirmasi sudah upload manual ke Adobe (markAsSubmitted).
export const STATUS_CONFIG = {
  draft: { label: "Draft", color: "text-[var(--text-secondary)]", bg: "bg-[var(--bg-element)]", icon: CircleDot },
  processing: { label: "Processing", color: "text-[var(--accent-blue)]", bg: "bg-[var(--accent-blue)]/10", icon: Loader2 },
  metadata_ready: { label: "Metadata Ready", color: "text-[var(--accent-blue)]", bg: "bg-[var(--accent-blue)]/10", icon: BadgeCheck },
  ready: { label: "Ready", color: "text-[var(--accent-green)]", bg: "bg-[var(--accent-green)]/10", icon: BadgeCheck },
  needs_review: { label: "Needs Review", color: "text-[var(--accent-gold)]", bg: "bg-[var(--accent-gold)]/10", icon: AlertTriangle },
  rejected: { label: "Rejected", color: "text-[var(--accent-red)]", bg: "bg-[var(--accent-red)]/10", icon: XCircle },
  exported: { label: "Exported", color: "text-[var(--accent-blue)]", bg: "bg-[var(--accent-blue)]/10", icon: Download },
  submitted: { label: "Submitted", color: "text-[var(--accent-gold)]", bg: "bg-[var(--accent-gold)]/10", icon: Rocket },
};

